/// <reference types="react" />
export interface Palette {
    title: string;
    expandable: boolean;
    configurable: boolean;
    colors: string[];
}
export interface Props {
    name: string;
    animate?: boolean;
    hideColorManagerLinks?: boolean;
    showCustomInput?: boolean;
    showResetButton?: boolean;
    value: string;
    isEditMode?: boolean;
    palettes: Record<string, Palette>;
    onClickCurrentColor: () => void;
    onClickSwatch: (color: string, colorId?: number | string) => void;
    onColorSwatchContextMenu?: ({ colorId, colorValue, event, isCurrentColorSwatch, }: {
        colorId: number | string;
        colorValue: string;
        event: React.MouseEvent;
        isCurrentColorSwatch?: boolean;
    }) => void;
    onEditMode: (mode: boolean) => void;
    onEditPalette: (id: number, color: string) => void;
    onClickAddGlobalColor: () => void;
    onDeleteGlobalColor: (colorId: string) => void;
    previousPaletteMode: undefined | string;
    setPreviousPaletteMode: (paletteMode: undefined | string) => void;
    getGlobalColorValue: (id: string) => string;
    isActiveGlobalColor: (id: string) => boolean;
}
